import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Toast from './components/Toast';
import Login from './components/Login';
import Register from './components/Register';
import BookList from './components/BookList';
import RequestQueue from './components/RequestQueue';

function App() {
  const [user, setUser] = useState(null);
  const [showRegister, setShowRegister] = useState(false);
  const [page, setPage] = useState('books');
  const [toast, setToast] = useState('');

  const showToast = (msg) => {
    setToast(msg);
  };

  const handleLogout = () => {
    setUser(null);
    setPage('books');
    localStorage.removeItem('token');
    showToast('Logged out');
  };

  const handleNav = (navPage) => {
    setPage(navPage);
  };

  return (
    <div className="min-h-screen bg-gradient-primary flex flex-col items-center justify-start font-sans">
      <Toast message={toast} onClose={() => setToast('')} />
      <div className="mt-8 text-4xl font-extrabold text-white tracking-wide drop-shadow-lg md:text-5xl">
        Library Management System
      </div>
      {user && <Navbar user={user} onLogout={handleLogout} onNav={handleNav} />}
      {!user ? (
        showRegister ? (
          <>
            <Register onRegister={() => setShowRegister(false)} />
            <div className="text-white mt-4 text-center">
              Already have an account?{' '}
              <button 
                className="bg-transparent text-blue-300 border-none cursor-pointer underline hover:text-blue-200 transition-colors" 
                onClick={() => setShowRegister(false)}
              >
                Login
              </button>
            </div>
          </>
        ) : (
          <>
            <Login setUser={setUser} />
            <div className="text-white mt-4 text-center">
              Don't have an account?{' '}
              <button 
                className="bg-transparent text-blue-300 border-none cursor-pointer underline hover:text-blue-200 transition-colors" 
                onClick={() => setShowRegister(true)}
              >
                Register
              </button>
            </div>
          </>
        )
      ) : (
        <>
          <div className="text-white text-xl mb-6 text-center">
            Welcome, {user.name} ({user.role})
          </div>
          {page === 'books' && <BookList user={user} showToast={showToast} />}
          {user.role === 'librarian' && page === 'requests' && <RequestQueue user={user} showToast={showToast} />}
        </>
      )}
    </div>
  );
}

export default App;
